    print("=" * 60)
    print(f"总岗位数: {report['total_jobs']}")
    print(f"公司数: {report['companies_count']}")
    print(f"行业数: {report['industries_count']}")
    print(f"城市数: {report['cities_count']}")
    print()
    print("行业分布:")
    for industry, count in sorted(report['industries'].items(), key=lambda x: -x[1]):
        print(f"  {industry}: {count}个岗位")
    print()
    print("城市分布:")
    for city, count in sorted(report['cities'].items(), key=lambda x: -x[1]):
        print(f"  {city}: {count}个岗位")
    print()
    print("公司分布:")
    for company, info in sorted(report['companies'].items(), key=lambda x: -x[1]["count"]):
        print(f"  {company}: {info['count']}个岗位 (来源: {info['source']})")
    print()
    print(f"数据来源: {len(report['data_sources'])} 个官方招聘网站")
    print(f"数据采集时间: {report['data_collection_date']}")
    print(f"免责声明: {report['disclaimer']}")
